import base64,hashlib,lzma
def _load(name,payload,digest):
 text=lzma.decompress(base64.b85decode(payload)).decode()
 assert hashlib.sha256(text.encode()).hexdigest()==digest,name
 exec(compile(text,name,'exec'),globals())
