def _plain(value):
    if isinstance(value,dict):return {k:_plain(v) for k,v in value.items()}
    if isinstance(value,(tuple,list)):return [_plain(v) for v in value]
    if isinstance(value,Fraction):return str(value)
    return value


if __name__=='__main__':
    arg=sys.argv[1] if len(sys.argv)>1 else ''
    if arg=='--ledger':
        result=ledger();assert result['total']==EXPECTED_N
        print_ledger(result);print(json.dumps(result['memory'],sort_keys=True))
    elif arg=='--certificate':
        p=plan(256);value,residual=probability_certificate(p);assert value>=Fraction(39,100)
        print(json.dumps(dict(P_lower=str(value),residual={k:str(v) for k,v in residual.items()},plan=_plain(p)),sort_keys=True))
    elif arg=='--selftest':
        kernel_selftest()
        if 'acceptance_suite' in globals():print(json.dumps(acceptance_suite(),sort_keys=True))
    elif arg=='--acceptance':print(json.dumps(acceptance_suite(),sort_keys=True))
    elif arg=='--details':
        result=ledger();print(json.dumps(dict(ledger=_plain(result),loss=loss(result['plan']),
            recovery_overhead=recovery_overhead_bound()),sort_keys=True))
    elif arg=='--gen-c':sys.stdout.write(GEN_C)
    elif arg=='--native-image':
        pr=prog();rp=rec();images=Layout(5,TP_256).programs()
        print(json.dumps(dict(body=_encode_body([({'^':1,'&':2,'|':3}[o],d,a,b) for o,d,a,b in pr.recs]).hex(),
            recovery=encode_recovery(rp.init+rp.flat).hex(),initialization=len(rp.init),
            table={k:v.packed().hex() for k,v in images.items()}),sort_keys=True))
    else:json.dump(serve(json.load(sys.stdin)),sys.stdout)
